/*
  Import user ảo + review ảo cho SouvenirDb.
  Điểm chính:
  - Không dùng user_id cố định 101..122.
  - User ảo sẽ được tạo từ MAX(users.id) hiện tại của DB:
      user review01 = @base_user_id + 1
      user review22 = @base_user_id + 22
  - Review không ghi id cố định, để reviews.id tự AUTO_INCREMENT.
  - Đã bỏ review dùng user_id 123 trong file gốc vì đó là user thật/không phải user ảo.
*/

use inola;

SET NAMES utf8mb4;
SET @base_user_id := (SELECT COALESCE(MAX(id), 0) FROM users);

START TRANSACTION;



UPDATE `products` p
LEFT JOIN (
    SELECT
        product_id,
        ROUND(AVG(rating), 1) AS avg_rating,
        COUNT(*) AS review_count
    FROM `reviews`
    GROUP BY product_id
) r ON r.product_id = p.id
SET
    p.avg_rating = COALESCE(r.avg_rating, 0),
    p.review_count = COALESCE(r.review_count, 0)
WHERE p.id > 0;

COMMIT;

-- Kiểm tra nhanh sau khi chạy:
SELECT @base_user_id AS base_user_id_before_import;
SELECT COUNT(*) AS fake_users_inserted
FROM users
WHERE id BETWEEN @base_user_id + 1 AND @base_user_id + 22;

SELECT COUNT(*) AS reviews_of_new_fake_users
FROM reviews
WHERE user_id BETWEEN @base_user_id + 1 AND @base_user_id + 22;
