(1, @base_user_id + 1, 5, 'Giao hàng nhanh, sản phẩm đúng mô tả, sẽ cân nhắc mua lại. Rất hài lòng.', '2026-01-17 19:28:16'),
(1, @base_user_id + 2, 5, 'Mua làm quà cho người thân, mọi người khen vị ngon và lạ miệng. Rất đáng để giới thiệu.', '2026-01-16 21:13:00'),
(1, @base_user_id + 3, 4, 'Hương vị khá truyền thống, ăn thử thấy hợp khẩu vị gia đình. Sẽ cân nhắc mua lại khi cần.', '2026-01-19 20:47:10'),
(1, @base_user_id + 4, 5, 'Sản phẩm nhìn chỉn chu, phù hợp để biếu hoặc dùng trong bữa ăn. Rất hài lòng.', '2026-01-22 08:00:57'),
(1, @base_user_id + 5, 4, 'Phần gia vị đậm đà, bảo quản dễ, phù hợp mua về dùng dần. Mình hài lòng với đơn hàng này.', '2026-01-19 01:03:24'),
(1, @base_user_id + 6, 4, 'Chất lượng ổn định, không bị khô, đóng gói vệ sinh. Sẽ cân nhắc mua lại khi cần.', '2026-01-19 14:48:53'),
(1, @base_user_id + 7, 5, 'Sản phẩm thơm, không bị quá mặn, dùng với cơm hoặc làm món nhắm đều hợp. Rất hài lòng.', '2026-01-19 10:58:27'),
